// ============================================================
// HELPERS
// ============================================================

function normalizeText(value) {
  return String(value ?? '')
    .normalize('NFD')
    .replace(/[\u0300-\u036f]/g, '')
    .replace(/Ă„â€˜/g, 'd')
    .replace(/Ă„Â/g, 'D')
    .toLowerCase()
    .trim();
}

function compactText(value) {
  return normalizeText(value)
    .replace(/[^a-z0-9]/g, '');
}

function parseCapacity(value) {
  if (value === null || value === undefined || value === '') {
    return null;
  }

  const text = normalizeText(value).replace(/\s+/g, '');

  const match = text.match(/(\d+(?:\.\d+)?)(tb|gb)?/i);

  if (!match) return null;

  let number = Number(match[1]);

  if (!Number.isFinite(number)) {
    return null;
  }

  if ((match[2] || '').toLowerCase() === 'tb') {
    number *= 1024;
  }

  return number;
}

function findAttribute(attributes, possibleNames) {
  if (!attributes || typeof attributes !== 'object') {
    return null;
  }

  for (const [key, value] of Object.entries(attributes)) {
    const normalizedKey = normalizeText(key);

    if (
      possibleNames.some(
        name => normalizedKey === normalizeText(name)
      )
    ) {
      return value;
    }
  }

  return null;
}

function getSpecification(specifications, keyword) {
  if (!Array.isArray(specifications)) {
    return null;
  }

  const normalizedKeyword = normalizeText(keyword);

  const item = specifications.find(spec => {
    const key =
      spec?.key ??
      spec?.name ??
      spec?.label ??
      '';

    return normalizeText(key).includes(normalizedKeyword);
  });

  return item?.value ?? null;
}

// ============================================================
// LAPTOP / VERSION PARSING
// VÄ‚Â­ dĂ¡Â»Â¥:
// "18 CPU - 40GPU - 48GB - 2TB"
// ============================================================

function extractVersionInfo(attributes) {
  const version = findAttribute(
    attributes,
    ['Phiên bản', 'Phien ban', 'Version']
  );

  if (!version) {
    return {
      storageGb: null,
      ramGb: null
    };
  }

  const text = String(version);

  const capacityMatches = [
    ...text.matchAll(/(\d+(?:\.\d+)?)\s*(TB|GB)/gi)
  ];

  if (capacityMatches.length === 0) {
    return {
      storageGb: null,
      ramGb: null
    };
  }

  const values = capacityMatches.map(match => ({
    value: Number(match[1]),
    unit: match[2].toUpperCase()
  }));

  // TB gĂ¡ÂºÂ§n nhĂ†Â° chĂ¡ÂºÂ¯c chĂ¡ÂºÂ¯n lÄ‚Â  storage
  const tbValue = values.find(v => v.unit === 'TB');

  let storageGb = null;
  let ramGb = null;

  if (tbValue) {
    storageGb = tbValue.value * 1024;

    const gbValues = values.filter(v => v.unit === 'GB');

    if (gbValues.length > 0) {
      ramGb = gbValues[0].value;
    }
  } else {
    // NĂ¡ÂºÂ¿u chĂ¡Â»â€° cÄ‚Â³ GB:
    // giÄ‚Â¡ trĂ¡Â»â€¹ lĂ¡Â»â€ºn cuĂ¡Â»â€˜i thĂ†Â°Ă¡Â»Âng lÄ‚Â  storage,
    // giÄ‚Â¡ trĂ¡Â»â€¹ nhĂ¡Â»Â Ă„â€˜Ă¡ÂºÂ§u cÄ‚Â³ thĂ¡Â»Æ’ lÄ‚Â  RAM.
    const gbValues = values
      .filter(v => v.unit === 'GB')
      .map(v => v.value);

    if (gbValues.length >= 2) {
      ramGb = gbValues[0];
      storageGb = gbValues[gbValues.length - 1];
    } else if (gbValues.length === 1) {
      storageGb = gbValues[0];
    }
  }

  return {
    storageGb,
    ramGb
  };
}

// ============================================================
