if (
  inputItems.length === 1 &&
  Array.isArray(inputItems[0].json)
) {
  apiProducts = inputItems[0].json;
} else {
  // TrĂ†Â°Ă¡Â»Âng hĂ¡Â»Â£p n8n split Product[] thÄ‚Â nh nhiĂ¡Â»Âu items
  apiProducts = inputItems.map(item => item.json);
}

// ============================================================

// ============================================================
const contextState = source.conversationState && typeof source.conversationState === 'object'
  ? source.conversationState
  : {};

function contextNormalize(value) {
  return String(value ?? '')
    .replace(/[đĐ]/g, 'd')
    .normalize('NFD')
    .replace(/[\u0300-\u036f]/g, '')
    .toLowerCase()
    .replace(/[^a-z0-9]+/g, ' ')
    .trim();
}

const contextCanonicalBrands = new Set([
  'apple', 'samsung', 'xiaomi', 'oppo', 'oneplus', 'vivo', 'honor', 'google', 'huawei', 'realme'
]);

function contextCanonicalBrand(value) {
  const text = contextNormalize(value);
  if (!text) return null;

  for (const brand of contextCanonicalBrands) {
    if (text === brand) {
      return brand;
    }
  }

  return null;
}

function unique(values) {
  return [...new Set(values.filter(Boolean))];
}

const contextCategory = source.category || contextState.category || null;
const contextExcludedBrands = unique([
  ...(Array.isArray(source.exclude_brands) ? source.exclude_brands : []),
  ...(Array.isArray(source.excluded_brands) ? source.excluded_brands : []),
  ...(Array.isArray(contextState.excluded_brands) ? contextState.excluded_brands : [])
].map(contextCanonicalBrand));
const contextExcludedForFilter = contextExcludedBrands;
const contextPreferredBrands = unique([
  ...(Array.isArray(source.preferred_brands) ? source.preferred_brands : []),
  ...(Array.isArray(contextState.preferred_brands) ? contextState.preferred_brands : [])
].map(contextCanonicalBrand));
const contextBrandSwitch =
  source.turn_action === 'EXCLUDE' &&
  contextExcludedBrands.some(brand => contextPreferredBrands.includes(brand));

const contextRequestedBrand = source.turn_action === 'EXCLUDE'
  ? null
  : contextCanonicalBrand(source.brand) ||
    contextCanonicalBrand(typeof filters !== 'undefined' ? filters.brand : null) ||
    contextCanonicalBrand(contextState.active_filters?.brand) ||
    null;

function contextProductMatchesBrand(product, brand) {
  if (!brand) return false;

  const values = [
    product?.brand,
    product?.category?.name,
    product?.category?.slug,
    product?.name
  ];

  return values.some(value =>
    contextCanonicalBrand(value) === brand
  );
}

function contextProductMatchesCategory(product, category) {
  if (!category) return true;

  const categoryText = contextNormalize([
    product?.category?.name,
    product?.category?.slug,
    product?.name,
    product?.brand
  ].filter(Boolean).join(' '));

  if (category === 'phone') {
    if (
      /watch|smartwatch|dong ho|tablet|ipad|laptop|macbook/.test(categoryText)
    ) {
      return false;
    }

    return (
      /dien thoai|smartphone|iphone|galaxy|redmi|poco|xiaomi|oppo|oneplus|samsung|apple/.test(categoryText)
    );
  }

  if (category === 'watch') {
    return /watch|smartwatch|dong ho/.test(categoryText);
  }

  if (category === 'laptop') {
    return /laptop|macbook|may tinh xach tay/.test(categoryText);
  }

  if (category === 'tablet') {
    return /tablet|ipad|may tinh bang/.test(categoryText);
  }

  return true;
}

// FILTERS FROM INTENT ROUTER
// ============================================================

const routedBrandFilter =
  normalizeText(source.brand);

const brandFilter = source.turn_action === 'EXCLUDE'
  ? ''
  : contextRequestedBrand || routedBrandFilter;

const modelFilter =
  compactText(source.model);

const colorFilter =
  normalizeText(source.color);

const storageFilter =
  source.storage_gb !== null &&
  source.storage_gb !== undefined
    ? Number(source.storage_gb)
    : null;

const ramFilter =
  source.ram_gb !== null &&
  source.ram_gb !== undefined
    ? Number(source.ram_gb)
    : null;

let priceMax =
  source.price_max !== null &&
  source.price_max !== undefined
    ? Number(source.price_max)
    : null;

if (priceMax === null && source.price_direction === 'lower') {
  const reference = Array.isArray(contextState.last_result_set)
    ? contextState.last_result_set.find(item => item.id === contextState.selected_product_id)
    : null;
  const referencePrice = Number(reference?.price_min ?? reference?.price_max);
  if (Number.isFinite(referencePrice)) priceMax = Math.max(0, referencePrice - 1);
}

// ============================================================
// SEARCH
// ============================================================

const results = [];

for (const product of apiProducts) {

  // ChĂ¡Â»â€° product active
  if (normalizeText(product.status) !== 'active') {
    continue;
  }

  // Category inactive thÄ‚Â¬ khÄ‚Â´ng tĂ†Â° vĂ¡ÂºÂ¥n
  if (product.category?.isActive === false) {
    continue;
  }

  if (
    contextCategory &&
    !contextProductMatchesCategory(product, contextCategory)
  ) {
    continue;
  }

  if (
    contextExcludedForFilter.some(brand =>
      contextProductMatchesBrand(product, brand)
    )
  ) {
    continue;
  }

  if (
    contextRequestedBrand &&
    !contextProductMatchesBrand(product, contextRequestedBrand)
  ) {
    continue;
  }


  // ----------------------------------------------------------
  // BRAND FILTER
  // ----------------------------------------------------------

  if (brandFilter) {
    const productBrand =
      normalizeText(product.brand);

    const categoryName =
      normalizeText(product.category?.name);

    const categorySlug =
      normalizeText(product.category?.slug);

    const matched =
      productBrand === brandFilter ||
      categoryName === brandFilter ||
      categorySlug === brandFilter;

    if (!matched) {
      continue;
    }
  }

  // ----------------------------------------------------------
  // MODEL FILTER
  // Product schema hiĂ¡Â»â€¡n tĂ¡ÂºÂ¡i dÄ‚Â¹ng name
  // ----------------------------------------------------------

  if (modelFilter) {
    const productName =
      compactText(product.name);

    if (!productName.includes(modelFilter)) {
      continue;
    }
  }

  const variants = Array.isArray(product.variants)
    ? product.variants
    : [];

  const matchedVariants = [];

  for (const variant of variants) {

    // --------------------------------------------------------
    // STOCK
    // --------------------------------------------------------

    const stock =
      Number(variant.stock) || 0;

    if (stock <= 0) {
      continue;
    }

    // --------------------------------------------------------
    // ATTRIBUTES
    // --------------------------------------------------------

    const directStorage = findAttribute(
      variant.attributes,
      [
        'Dung lÆ°á»£ng',
        'Dung luong',
        'Storage',
        'SSD'
      ]
    );

    const directRam = findAttribute(
      variant.attributes,
      ['RAM']
    );

    const colorRaw = findAttribute(
      variant.attributes,
      [
        'Màu sắc',
        'Mau sac',
        'Color'
      ]
    );

    const versionInfo =
      extractVersionInfo(variant.attributes);

    let storageGb =
      parseCapacity(directStorage);

    let ramGb =
      parseCapacity(directRam);

    // Laptop/MacBook Ă„â€˜ang dÄ‚Â¹ng "PhiÄ‚Âªn bĂ¡ÂºÂ£n"
    if (storageGb === null) {
      storageGb =
        versionInfo.storageGb;
    }

    if (ramGb === null) {
      ramGb =
        versionInfo.ramGb;
    }

    // Fallback RAM tĂ¡Â»Â« specifications
    if (ramGb === null) {
      ramGb = parseCapacity(
        getSpecification(
          product.specifications,
          'RAM'
        )
      );
    }

    // --------------------------------------------------------
    // STORAGE FILTER
    // --------------------------------------------------------

    if (
      storageFilter !== null &&
      storageGb !== storageFilter
    ) {
      continue;
    }

    // --------------------------------------------------------
    // RAM FILTER
    // --------------------------------------------------------

    if (
      ramFilter !== null &&
      ramGb !== ramFilter
    ) {
      continue;
    }

    // --------------------------------------------------------
    // COLOR FILTER
    // --------------------------------------------------------

    if (colorFilter) {
      if (
        !normalizeText(colorRaw)
          .includes(colorFilter)
      ) {
        continue;
      }
    }

    // --------------------------------------------------------
    // PRICE
    // --------------------------------------------------------

    const originalPrice =
      Number(variant.price) || 0;

    // CANDIDATE FIX LIVE-04: prefer a valid per-variant salePrice when
    // no campaign exists. Campaign-only and overlap keep legacy behavior.
    if (!Number.isFinite(originalPrice) || originalPrice <= 0) continue;
    const candidateSalePrice = Number(variant.salePrice);
    const validSalePrice = variant.salePrice != null && variant.salePrice !== '' &&
      Number.isFinite(candidateSalePrice) && candidateSalePrice > 0 && candidateSalePrice < originalPrice;
    const effectivePrice = product.activeCampaign
      ? calculateCampaignPrice(originalPrice, product.activeCampaign)
      : (validSalePrice ? candidateSalePrice : originalPrice);

    if (
      priceMax !== null &&
      effectivePrice > priceMax
    ) {
      continue;
    }

    const imageUrl =
      normalizeImageUrl(
        variant.image ||
        product.image ||
        product.images?.[0]
      );

    matchedVariants.push({
      id: variant.id,

      sku: variant.sku,

      attributes:
        variant.attributes ?? {},

      storage_gb:
        storageGb,

      ram_gb:
        ramGb,

      color:
        colorRaw ?? null,

      color_code:
        variant.colorCode ?? null,

      original_price:
        originalPrice,

      price:
        effectivePrice,

      sale_price:
        variant.salePrice ?? null,

      stock,

      image_url:
        imageUrl
    });
  }

  // KhÄ‚Â´ng cÄ‚Â³ variant cÄ‚Â²n hÄ‚Â ng/phÄ‚Â¹ hĂ¡Â»Â£p
  if (matchedVariants.length === 0) {
    continue;
  }

  matchedVariants.sort(
    (a, b) => a.price - b.price
  );

  const cheapestVariant =
    matchedVariants[0];

  const highestPrice =
    Math.max(
      ...matchedVariants.map(v => v.price)
    );

  const totalStock =
    matchedVariants.reduce(
      (sum, variant) =>
        sum + variant.stock,
      0
    );

  results.push({
    id: product.id,

    name: product.name,

    // GiĂ¡Â»Â¯ compatibility vĂ¡Â»â€ºi prompt cĂ…Â©
    model: product.name,

    brand:
      product.brand ?? null,

    category: product.category
      ? {
          id: product.category.id,
          name: product.category.name,
          slug: product.category.slug
        }
      : null,

    description:
      product.description ?? null,

    image_url:
      normalizeImageUrl(
        cheapestVariant.image_url ||
        product.image ||
        product.images?.[0]
      ),

    images:
      Array.isArray(product.images)
        ? product.images
            .map(normalizeImageUrl)
            .filter(Boolean)
        : [],

    price:
      cheapestVariant.price,

    price_min:
      cheapestVariant.price,

    price_max:
      highestPrice,

    original_price:
      cheapestVariant.price < cheapestVariant.original_price
        ? cheapestVariant.original_price
        : null,

    stock:
      totalStock,

    availability:
      totalStock > 0
        ? 'in_stock'
        : 'out_of_stock',

    variant_id:
      cheapestVariant.id,

    sku:
      cheapestVariant.sku,

    storage_gb:
      cheapestVariant.storage_gb,

    ram_gb:
      cheapestVariant.ram_gb,

    color:
      cheapestVariant.color,

    specifications:
      product.specifications ?? [],

    screen:
      getSpecification(
        product.specifications,
        'Màn hình'
      ),

    cpu:
      getSpecification(
        product.specifications,
        'CPU'
      ) ||
      getSpecification(
        product.specifications,
        'Chip'
      ),

    camera:
      getSpecification(
        product.specifications,
        'Camera'
      ),

    battery:
      getSpecification(
        product.specifications,
        'Pin'
      ),

    operating_system:
      getSpecification(
        product.specifications,
        'Hệ điều hành'
      ),

    campaign:
      product.activeCampaign
        ? {
            id:
              product.activeCampaign.id,

            name:
              product.activeCampaign.name,

            discountType:
              product.activeCampaign.discountType,

            discountValue:
              product.activeCampaign.discountValue
          }
        : null,

    variants:
      matchedVariants
  });
}

// ============================================================
// SORT + LIMIT
// ============================================================

results.sort(
  (a, b) => a.price - b.price
);

const products =
  results.slice(0, contextBrandSwitch ? 3 : 20);

// ============================================================
// OUTPUT
// ============================================================

return [
  {
    json: {
      result_type:
        products.length > 0
          ? 'product_search'
          : 'no_result',

      total:
        products.length,

      intent:
        'product_search',

      chatInput:
        source.chatInput ?? '',

      sessionId:
        source.sessionId ?? '',

      source:
        source.source ?? 'web_chat',

      products,

      turn_action: source.turn_action ?? null,
      context_mode: source.context_mode ?? 'continue',
      category: source.category ?? null,
      requires_clarification: source.requires_clarification === true,
      clarification_field: source.clarification_field ?? null
    }
  }
];

const input = $json;

function normalizeStorage(value) {
  if (!value) return null;

  const text = String(value)
    .toLowerCase()
    .replace(/\s/g, '');

  if (text.includes('1tb')) {
    return 1024;
  }

  const match = text.match(/(\d+)/);

  return match ? Number(match[1]) : null;
}

function normalizeRam(value) {
  if (!value) return null;

  const match = String(value).match(/(\d+)/);

  return match ? Number(match[1]) : null;
}

return [
  {
    json: {
      intent: "product_detail",

      selected_product_id: input.selected_product_id || null,

      conversationState: input.conversationState || null,

      price_max: input.price_max ?? input.conversationState?.active_filters?.price_max ?? null,

      brand: input.brand || null,

      model: input.model || null,

      storage_gb: normalizeStorage(input.storage),

      ram_gb: normalizeRam(input.ram),

      color: input.color || null,

      condition_type: input.condition || null,

      chatInput: input.chatInput || "",

      sessionId: input.sessionId || "",

      source: input.source || "web_chat"
    }
  }
];

const source = $('Prepare Product Detail').first().json;

// ============================================================
// HELPERS
// ============================================================

function normalizeText(value) {
  return String(value ?? '')
    .normalize('NFD')
    .replace(/[\u0300-\u036f]/g, '')
    .replace(/Ă„â€˜/g, 'd')
    .replace(/Ă„Â/g, 'D')
    .toLowerCase()
    .trim();
}

function compactText(value) {
  return normalizeText(value)
    .replace(/[^a-z0-9]/g, '');
}

function parseCapacity(value) {
  if (value === null || value === undefined || value === '') {
    return null;
  }

  const text = normalizeText(value).replace(/\s+/g, '');

  const match = text.match(/(\d+(?:\.\d+)?)(tb|gb)?/i);

  if (!match) return null;

  let number = Number(match[1]);

  if (!Number.isFinite(number)) {
    return null;
  }

  if ((match[2] || '').toLowerCase() === 'tb') {
    number *= 1024;
  }

  return number;
}

function findAttribute(attributes, possibleNames) {
  if (!attributes || typeof attributes !== 'object') {
    return null;
  }

  for (const [key, value] of Object.entries(attributes)) {
    const normalizedKey = normalizeText(key);

    if (
      possibleNames.some(
        name => normalizedKey === normalizeText(name)
      )
    ) {
      return value;
    }
  }

  return null;
}

function getSpecification(specifications, keyword) {
  if (!Array.isArray(specifications)) {
    return null;
  }

  const target = normalizeText(keyword);

  const item = specifications.find(spec => {
    const key =
      spec?.key ??
      spec?.name ??
      spec?.label ??
      '';

    return normalizeText(key).includes(target);
  });

  return item?.value ?? null;
}

function extractVersionInfo(attributes) {
  const version = findAttribute(
    attributes,
    ['Phiên bản', 'Phien ban', 'Version']
  );

  if (!version) {
    return {
      storageGb: null,
      ramGb: null
    };
  }

  const matches = [
    ...String(version).matchAll(
      /(\d+(?:\.\d+)?)\s*(TB|GB)/gi
    )
  ];

  if (!matches.length) {
    return {
      storageGb: null,
      ramGb: null
    };
  }

  const values = matches.map(match => ({
    value: Number(match[1]),
    unit: match[2].toUpperCase()
  }));

  const tb = values.find(v => v.unit === 'TB');

  if (tb) {
    const gb = values.filter(v => v.unit === 'GB');

    return {
      storageGb: tb.value * 1024,
      ramGb: gb.length ? gb[0].value : null
    };
  }

  const gb = values
    .filter(v => v.unit === 'GB')
    .map(v => v.value);

  if (gb.length >= 2) {
    return {
      ramGb: gb[0],
      storageGb: gb[gb.length - 1]
    };
  }

  return {
    storageGb: gb.length === 1 ? gb[0] : null,
    ramGb: null
  };
}

function normalizeImageUrl(value) {
  if (!value) return null;

  let text = String(value).trim();

  const markdownMatch = text.match(
    /^\[([^\]]+)\]\(([^)]+)\)$/
  );

  if (markdownMatch) {
    text = markdownMatch[2] || markdownMatch[1];
  }

  text = text.replace(
    /^https?:\/\/localhost:3001/,
    ''
  );

  text = text.replace(
    /^https?:\/\/127\.0\.0\.1:3001/,
    ''
  );

  text = text.replace(
    /^https?:\/\/host\.docker\.internal:3001/,
    ''
  );

  return text || null;
}

function calculateCampaignPrice(price, campaign) {
  const originalPrice = Number(price);

  if (!Number.isFinite(originalPrice)) {
    return 0;
  }

  if (!campaign) {
    return originalPrice;
  }

  const discountValue =
    Number(campaign.discountValue) || 0;

  if (campaign.discountType === 'percentage') {
    return Math.max(
      0,
      Math.round(
        originalPrice -
        originalPrice * discountValue / 100
      )
    );
  }

  return Math.max(
    0,
    originalPrice - discountValue
  );
}

// ============================================================
// API INPUT
// ============================================================

const items = $input.all();

let apiProducts = [];

if (
  items.length === 1 &&
  Array.isArray(items[0].json)
) {
  apiProducts = items[0].json;
} else {
  apiProducts = items.map(item => item.json);
}

// ============================================================
// REQUEST FILTERS
// ============================================================

const brandFilter =
  normalizeText(source.brand);

const canonicalFilters = source.conversationState?.active_filters || {};
const effectiveBrandFilter = brandFilter || normalizeText(canonicalFilters.brand);
const selectedProductId = source.selected_product_id ? String(source.selected_product_id) : '';
const maxPriceFilter = source.price_max !== null && source.price_max !== undefined
  ? Number(source.price_max)
  : (canonicalFilters.price_max !== null && canonicalFilters.price_max !== undefined
      ? Number(canonicalFilters.price_max)
      : null);
const excludedBrandFilters = Array.isArray(source.conversationState?.excluded_brands)
  ? source.conversationState.excluded_brands.map(normalizeText)
  : [];

const modelFilter =
  compactText(source.model);

const colorFilter =
  normalizeText(source.color);

const storageFilter =
  source.storage_gb !== null &&
  source.storage_gb !== undefined
    ? Number(source.storage_gb)
    : null;

const ramFilter =
  source.ram_gb !== null &&
  source.ram_gb !== undefined
    ? Number(source.ram_gb)
    : null;

// ============================================================
// FIND PRODUCT
// ============================================================

const eligibleProducts = apiProducts.filter(product => {
  if (normalizeText(product.status) !== 'active' || product.category?.isActive === false) return false;
  const productBrands = [product.brand, product.category?.name, product.category?.slug]
    .filter(Boolean)
    .map(normalizeText);
  if (effectiveBrandFilter && !productBrands.includes(effectiveBrandFilter)) return false;
  if (excludedBrandFilters.some(brand => productBrands.includes(brand))) return false;
  return true;
});

let matchedProduct = null;
if (selectedProductId) {
  // A supplied canonical ID is authoritative. Do not fall back to a sibling SKU.
  matchedProduct = eligibleProducts.find(product => String(product.id) === selectedProductId) || null;
} else if (!modelFilter && !effectiveBrandFilter) {
  // An unreferenced detail request must not become a first-item catalog lookup.
  matchedProduct = null;
} else if (modelFilter) {
  const exactMatches = eligibleProducts.filter(product => compactText(product.name) === modelFilter);
  if (exactMatches.length === 1) {
    matchedProduct = exactMatches[0];
  } else if (exactMatches.length === 0) {
    const fuzzyMatches = eligibleProducts.filter(product => compactText(product.name).includes(modelFilter));
    if (fuzzyMatches.length === 1) matchedProduct = fuzzyMatches[0];
  }
} else {
  matchedProduct = eligibleProducts[0] || null;
}

// ============================================================
// NO PRODUCT
// ============================================================

if (!matchedProduct) {
  return [
    {
      json: {
        result_type: 'no_result',
        total: 0,
        intent: 'product_detail',

        chatInput:
          source.chatInput ?? '',

        sessionId:
          source.sessionId ?? '',

        product: null
      }
    }
  ];
}

// ============================================================
// FILTER VARIANTS
// ============================================================

const matchedVariants = [];

const variants = Array.isArray(matchedProduct.variants)
  ? matchedProduct.variants
  : [];

for (const variant of variants) {

  const storageRaw = findAttribute(
    variant.attributes,
    [
      'Dung lÆ°á»£ng',
      'Dung luong',
      'Storage',
      'SSD'
    ]
  );

  const colorRaw = findAttribute(
    variant.attributes,
    [
      'Màu sắc',
      'Mau sac',
      'Color'
    ]
  );

  const directRam = findAttribute(
    variant.attributes,
    ['RAM']
  );

  const versionInfo =
    extractVersionInfo(variant.attributes);

  let storageGb =
    parseCapacity(storageRaw);

  let ramGb =
    parseCapacity(directRam);

  if (storageGb === null) {
    storageGb =
      versionInfo.storageGb;
  }

  if (ramGb === null) {
    ramGb =
      versionInfo.ramGb;
  }

  if (ramGb === null) {
    ramGb = parseCapacity(
      getSpecification(
        matchedProduct.specifications,
        'RAM'
      )
    );
  }

  // Requested storage
  if (
    storageFilter !== null &&
    storageGb !== storageFilter
  ) {
    continue;
  }

  // Requested RAM
  if (
    ramFilter !== null &&
    ramGb !== ramFilter
  ) {
    continue;
  }

  // Requested color
  if (colorFilter) {
    if (
      !normalizeText(colorRaw)
        .includes(colorFilter)
    ) {
      continue;
    }
  }

  const stock =
    Number(variant.stock) || 0;

  const originalPrice =
    Number(variant.price) || 0;

  const effectivePrice =
    calculateCampaignPrice(
      originalPrice,
      matchedProduct.activeCampaign
    );

  if (Number.isFinite(maxPriceFilter) && effectivePrice > maxPriceFilter) {
    continue;
  }

  matchedVariants.push({
    id: variant.id,

    sku: variant.sku,

    attributes:
      variant.attributes ?? {},

    storage_gb:
      storageGb,

    ram_gb:
      ramGb,

    color:
      colorRaw ?? null,

    color_code:
      variant.colorCode ?? null,

    original_price:
      originalPrice,

    price:
      effectivePrice,

    sale_price:
      variant.salePrice ?? null,

    stock,

    availability:
      stock > 0
        ? 'in_stock'
        : 'out_of_stock',

    image_url:
      normalizeImageUrl(
        variant.image ||
        matchedProduct.image ||
        matchedProduct.images?.[0]
      )
  });
}

// ============================================================
// PRODUCT EXISTS BUT REQUESTED VARIANT DOES NOT
// ============================================================

if (matchedVariants.length === 0) {
  return [
    {
      json: {
        result_type: 'no_result',
        total: 0,
        intent: 'product_detail',

        chatInput:
          source.chatInput ?? '',

        sessionId:
          source.sessionId ?? '',

        product: null
      }
    }
  ];
}

// ============================================================
// SORT
// in-stock first, then price
// ============================================================

matchedVariants.sort((a, b) => {
  if (
    a.availability !== b.availability
  ) {
    return a.availability === 'in_stock'
      ? -1
      : 1;
  }

  return a.price - b.price;
});

const inStockVariants =
  matchedVariants.filter(
    v => v.stock > 0
  );

const totalStock =
  matchedVariants.reduce(
    (sum, v) => sum + v.stock,
    0
  );

const prices =
  matchedVariants.map(v => v.price);

const selectedVariant =
  matchedVariants[0];

// ============================================================
// FINAL PRODUCT
// ============================================================

const product = {
  id:
    matchedProduct.id,

  name:
    matchedProduct.name,

  model:
    matchedProduct.name,

  brand:
    matchedProduct.brand ?? null,

  category:
    matchedProduct.category
      ? {
          id: matchedProduct.category.id,
          name: matchedProduct.category.name,
          slug: matchedProduct.category.slug
        }
      : null,

  description:
    matchedProduct.description ?? null,

  image_url:
    normalizeImageUrl(
      selectedVariant.image_url ||
      matchedProduct.image ||
      matchedProduct.images?.[0]
    ),

  images:
    Array.isArray(matchedProduct.images)
      ? matchedProduct.images
          .map(normalizeImageUrl)
          .filter(Boolean)
      : [],

  specifications:
    matchedProduct.specifications ?? [],

  screen:
    getSpecification(
      matchedProduct.specifications,
      'Màn hình'
    ),

  cpu:
    getSpecification(
      matchedProduct.specifications,
      'CPU'
    ) ||
    getSpecification(
      matchedProduct.specifications,
      'Chip'
    ),

  camera:
    getSpecification(
      matchedProduct.specifications,
      'Camera'
    ),

  battery:
    getSpecification(
      matchedProduct.specifications,
      'Pin'
    ),

  operating_system:
    getSpecification(
      matchedProduct.specifications,
      'Hệ điều hành'
    ),

  price:
    Math.min(...prices),

  price_min:
    Math.min(...prices),

  price_max:
    Math.max(...prices),

  stock:
    totalStock,

  availability:
    inStockVariants.length > 0
      ? 'in_stock'
      : 'out_of_stock',

  campaign:
    matchedProduct.activeCampaign
      ? {
          id:
            matchedProduct.activeCampaign.id,

          name:
            matchedProduct.activeCampaign.name,

          discountType:
            matchedProduct.activeCampaign.discountType,

          discountValue:
            matchedProduct.activeCampaign.discountValue
        }
      : null,

  variants:
    matchedVariants
};

// ============================================================
// OUTPUT
// ============================================================

return [
  {
    json: {
      result_type:
        'product_detail',

      total: 1,

      intent:
        'product_detail',

      chatInput:
        source.chatInput ?? '',

      sessionId:
        source.sessionId ?? '',

      product
    }
  }
];

