const input = $json;

// ========================================
// LĂ¡ÂºÂ¥y danh sÄ‚Â¡ch sĂ¡ÂºÂ£n phĂ¡ÂºÂ©m cĂ¡ÂºÂ§n so sÄ‚Â¡nh
// ========================================

const products = Array.isArray(input.products)
  ? input.products
  : [];

// ========================================
// Normalize products
// ========================================

const normalizedProducts = products
  .map((product, index) => ({
    index: index + 1,

    brand: product.brand || null,

    model: product.model || null,

    storage_gb:
      product.storage_gb === null ||
      product.storage_gb === undefined ||
      product.storage_gb === ""
        ? null
        : Number(product.storage_gb),

    ram_gb:
      product.ram_gb === null ||
      product.ram_gb === undefined ||
      product.ram_gb === ""
        ? null
        : Number(product.ram_gb),

    color: product.color || null
  }))
  .filter(product => product.model);

// ========================================
// KiĂ¡Â»Æ’m tra sĂ¡Â»â€˜ lĂ†Â°Ă¡Â»Â£ng sĂ¡ÂºÂ£n phĂ¡ÂºÂ©m
// ========================================

if (normalizedProducts.length < 2) {
  throw new Error(
    "Product Compare cần ít nhất 2 sản phẩm."
  );
}

// ========================================
// Output
// ========================================

return [
  {
    json: {
      result_type: "product_compare",

      total_requested: normalizedProducts.length,

      products: normalizedProducts,

      chatInput: input.chatInput || "",

      sessionId: input.sessionId || "",

      source: input.source || "web_chat"
    }
  }
];

const source = $('Prepare Compare Filters').first().json;

// ============================================================
// HELPERS
// ============================================================

function normalizeText(value) {
  return String(value ?? '')
    .normalize('NFD')
    .replace(/[\u0300-\u036f]/g, '')
    .replace(/Ă„â€˜/g, 'd')
    .replace(/Ă„Â/g, 'D')
    .toLowerCase()
    .trim();
}

function compactText(value) {
  return normalizeText(value)
    .replace(/[^a-z0-9]/g, '');
}

function parseCapacity(value) {
  if (
    value === null ||
    value === undefined ||
    value === ''
  ) {
    return null;
  }

  const text = normalizeText(value)
    .replace(/\s+/g, '');

  const match = text.match(
    /(\d+(?:\.\d+)?)(tb|gb)?/i
  );

  if (!match) {
    return null;
  }

  let number = Number(match[1]);

  if (!Number.isFinite(number)) {
    return null;
  }

  const unit = (match[2] || '')
    .toLowerCase();

  if (unit === 'tb') {
    number *= 1024;
  }

  return number;
}

function findAttribute(
  attributes,
  possibleNames
) {
  if (
    !attributes ||
    typeof attributes !== 'object'
  ) {
    return null;
  }

  for (
    const [key, value]
    of Object.entries(attributes)
  ) {
    const normalizedKey =
      normalizeText(key);

    const matched =
      possibleNames.some(name => {
        return (
          normalizedKey ===
          normalizeText(name)
        );
      });

    if (matched) {
      return value;
    }
  }

  return null;
}

function getSpecification(
  specifications,
  keyword
) {
  if (!Array.isArray(specifications)) {
    return null;
  }

  const target =
    normalizeText(keyword);

  const item =
    specifications.find(spec => {
      const key =
        spec?.key ??
        spec?.name ??
        spec?.label ??
        '';

      return normalizeText(key)
        .includes(target);
    });

  return item?.value ?? null;
}

function extractVersionInfo(attributes) {
  const version =
    findAttribute(
      attributes,
      [
        'Phiên bản',
        'Phien ban',
        'Version'
      ]
    );

  if (!version) {
    return {
      storageGb: null,
      ramGb: null
    };
  }

  const matches = [
    ...String(version).matchAll(
      /(\d+(?:\.\d+)?)\s*(TB|GB)/gi
    )
  ];

  if (!matches.length) {
    return {
      storageGb: null,
      ramGb: null
    };
  }

  const values =
    matches.map(match => ({
      value: Number(match[1]),
      unit: match[2].toUpperCase()
    }));

  // VÄ‚Â­ dĂ¡Â»Â¥:
  // 48GB - 2TB
  const tb =
    values.find(
      item => item.unit === 'TB'
    );

  if (tb) {
    const gbValues =
      values.filter(
        item => item.unit === 'GB'
      );

    return {
      storageGb:
        tb.value * 1024,

      ramGb:
        gbValues.length
          ? gbValues[0].value
          : null
    };
  }

  const gbValues =
    values
      .filter(
        item => item.unit === 'GB'
      )
      .map(
        item => item.value
      );

  if (gbValues.length >= 2) {
    return {
      ramGb:
        gbValues[0],

      storageGb:
        gbValues[
          gbValues.length - 1
        ]
    };
  }

  return {
    storageGb:
      gbValues.length === 1
        ? gbValues[0]
        : null,

    ramGb: null
  };
}

function normalizeImageUrl(value) {
  if (!value) {
    return null;
  }

  let text =
    String(value).trim();

  // TrĂ†Â°Ă¡Â»Âng hĂ¡Â»Â£p vÄ‚Â´ tÄ‚Â¬nh lÄ‚Â  markdown:
  // [url](url)
  const markdownMatch =
    text.match(
      /^\[([^\]]+)\]\(([^)]+)\)$/
    );

  if (markdownMatch) {
    text =
      markdownMatch[2] ||
      markdownMatch[1];
  }

  text = text.replace(
    /^https?:\/\/localhost:3001/,
    ''
  );

  text = text.replace(
    /^https?:\/\/127\.0\.0\.1:3001/,
    ''
  );

  text = text.replace(
    /^https?:\/\/host\.docker\.internal:3001/,
    ''
  );

  return text || null;
}

function calculateCampaignPrice(
  price,
  campaign
) {
  const originalPrice =
    Number(price);

  if (!Number.isFinite(originalPrice)) {
    return 0;
  }

  if (!campaign) {
    return originalPrice;
  }

  const discountValue =
    Number(campaign.discountValue) || 0;

  if (
    campaign.discountType ===
    'percentage'
  ) {
    return Math.max(
      0,
      Math.round(
        originalPrice -
        (
          originalPrice *
          discountValue /
          100
        )
      )
    );
  }

  if (
    campaign.discountType === 'fixed'
  ) {
    return Math.max(
      0,
      originalPrice - discountValue
    );
  }

  return originalPrice;
}

// ============================================================
// API PRODUCTS
// ============================================================

const items = $input.all();

let apiProducts = [];

if (
  items.length === 1 &&
  Array.isArray(items[0].json)
) {
  apiProducts =
    items[0].json;
} else {
  apiProducts =
    items.map(
      item => item.json
    );
}

// ============================================================
// CHĂ¡Â»Ë† GIĂ¡Â»Â® PRODUCT ACTIVE
// ============================================================

apiProducts =
  apiProducts.filter(product => {

    if (
      normalizeText(product.status)
      !== 'active'
    ) {
      return false;
    }

    if (
      product.category?.isActive === false
    ) {
      return false;
    }

    return true;
  });

// ============================================================
// REQUESTED PRODUCTS
// ============================================================

const requestedProducts =
  Array.isArray(source.products)
    ? source.products
    : [];

const comparedProducts = [];

const missingProducts = [];

// ============================================================
// XĂ¡Â»Â¬ LÄ‚Â TĂ¡Â»ÂªNG SĂ¡ÂºÂ¢N PHĂ¡ÂºÂ¨M NGĂ†Â¯Ă¡Â»Å“I DÄ‚â„¢NG MUĂ¡Â»ÂN SO SÄ‚ÂNH
// ============================================================

for (
  const requested
  of requestedProducts
) {

  // ==========================================================
  // NORMALIZE REQUEST FILTER
  // ==========================================================

  const requestedBrand =
    normalizeText(
      requested.brand
    );

  const requestedModel =
    compactText(
      requested.model
    );

  const requestedColor =
    normalizeText(
      requested.color
    );

  const requestedStorage =
    requested.storage_gb === null ||
    requested.storage_gb === undefined ||
    requested.storage_gb === ''
      ? null
      : Number(
          requested.storage_gb
        );

  const requestedRam =
    requested.ram_gb === null ||
    requested.ram_gb === undefined ||
    requested.ram_gb === ''
      ? null
      : Number(
          requested.ram_gb
        );

  // ==========================================================
  // TÄ‚Å’M BASE PRODUCT
  // ==========================================================

  const matchedProduct =
    apiProducts.find(product => {

      // --------------------------------------------------------
      // BRAND
      // --------------------------------------------------------

      if (requestedBrand) {

        const productBrand =
          normalizeText(
            product.brand
          );

        const categoryName =
          normalizeText(
            product.category?.name
          );

        const categorySlug =
          normalizeText(
            product.category?.slug
          );

        if (
          productBrand !== requestedBrand &&
          categoryName !== requestedBrand &&
          categorySlug !== requestedBrand
        ) {
          return false;
        }
      }

      // --------------------------------------------------------
      // MODEL / PRODUCT NAME
      // --------------------------------------------------------

      if (requestedModel) {

        const productName =
          compactText(
            product.name
          );

        // LIVE-17: exact model identity, with ONLY the catalog brand prefix
        // permitted to differ. A short model must not match a Pro/Pro Max.
        const productBrandPrefix = compactText(product.brand || '');
        const withoutBrand = productBrandPrefix && productName.startsWith(productBrandPrefix)
          ? productName.slice(productBrandPrefix.length) : productName;
        const modelMatched = productName === requestedModel || withoutBrand === requestedModel;

        if (!modelMatched) {
          return false;
        }
      }

      return true;
    });

  // ==========================================================
  // KHÄ‚â€NG TÄ‚Å’M THĂ¡ÂºÂ¤Y PRODUCT
  // ==========================================================

  if (!matchedProduct) {

    missingProducts.push({
      index:
        requested.index ?? null,

      brand:
        requested.brand ?? null,

      model:
        requested.model ?? null,

      storage_gb:
        requestedStorage,

      ram_gb:
        requestedRam,

      color:
        requested.color ?? null,

      reason:
        'product_not_found'
    });

    continue;
  }

  // ==========================================================
  // VARIANTS
  // ==========================================================

  const variants =
    Array.isArray(
      matchedProduct.variants
    )
      ? matchedProduct.variants
      : [];

  const matchedVariants = [];

  for (
    const variant
    of variants
  ) {

    // --------------------------------------------------------
    // STORAGE
    // --------------------------------------------------------

    const storageRaw =
      findAttribute(
        variant.attributes,
        [
          'Dung lÆ°á»£ng',
          'Dung luong',
          'Storage',
          'SSD'
        ]
      );

    // --------------------------------------------------------
    // COLOR
    // --------------------------------------------------------

    const colorRaw =
      findAttribute(
        variant.attributes,
        [
          'Màu sắc',
          'Mau sac',
          'Color'
        ]
      );

    // --------------------------------------------------------
    // RAM
    // --------------------------------------------------------

    const directRam =
      findAttribute(
        variant.attributes,
        [
          'RAM'
        ]
      );

    // --------------------------------------------------------
    // LAPTOP VERSION
    // --------------------------------------------------------

    const versionInfo =
      extractVersionInfo(
        variant.attributes
      );

    let storageGb =
      parseCapacity(
        storageRaw
      );

    let ramGb =
      parseCapacity(
        directRam
      );

    if (storageGb === null) {
      storageGb =
        versionInfo.storageGb;
    }

    if (ramGb === null) {
      ramGb =
        versionInfo.ramGb;
    }

    // NĂ¡ÂºÂ¿u variant khÄ‚Â´ng cÄ‚Â³ RAM
    // thÄ‚Â¬ thĂ¡Â»Â­ lĂ¡ÂºÂ¥y RAM tĂ¡Â»Â« specifications cĂ¡Â»Â§a Product
    if (ramGb === null) {
      ramGb =
        parseCapacity(
          getSpecification(
            matchedProduct.specifications,
            'RAM'
          )
        );
    }

    // ========================================================
    // FILTER STORAGE
    // ========================================================

    if (
      requestedStorage !== null &&
      storageGb !== requestedStorage
    ) {
      continue;
    }

    // ========================================================
    // FILTER RAM
    // ========================================================

    if (
      requestedRam !== null &&
      ramGb !== requestedRam
    ) {
      continue;
    }

    // ========================================================
    // FILTER COLOR
    // ========================================================

    if (requestedColor) {

      if (
        !normalizeText(colorRaw)
          .includes(
            requestedColor
          )
      ) {
        continue;
      }
    }

    // ========================================================
    // PRICE + STOCK
    // ========================================================

    const stock =
      Number(
        variant.stock
      ) || 0;

    const originalPrice =
      Number(
        variant.price
      ) || 0;

    if (!Number.isFinite(originalPrice) || originalPrice <= 0) continue;
    const candidateSalePrice = Number(variant.salePrice);
    const validSalePrice = variant.salePrice != null && variant.salePrice !== '' &&
      Number.isFinite(candidateSalePrice) && candidateSalePrice > 0 && candidateSalePrice < originalPrice;
    const currentPrice = matchedProduct.activeCampaign
      ? calculateCampaignPrice(originalPrice, matchedProduct.activeCampaign)
      : (validSalePrice ? candidateSalePrice : originalPrice);

    matchedVariants.push({

      id:
        variant.id,

      sku:
        variant.sku,

      attributes:
        variant.attributes ?? {},

      storage_gb:
        storageGb,

      ram_gb:
        ramGb,

      color:
        colorRaw ?? null,

      color_code:
        variant.colorCode ?? null,

      original_price:
        originalPrice,

      price:
        currentPrice,

      sale_price:
        variant.salePrice ?? null,

      stock,

      availability:
        stock > 0
          ? 'in_stock'
          : 'out_of_stock',

      image_url:
        normalizeImageUrl(
          variant.image ||
          matchedProduct.image ||
          matchedProduct.images?.[0]
        )
    });
  }

  // ==========================================================
  // PRODUCT TĂ¡Â»â€™N TĂ¡ÂºÂ I NHĂ†Â¯NG VARIANT YÄ‚ÂU CĂ¡ÂºÂ¦U KHÄ‚â€NG TĂ¡Â»â€™N TĂ¡ÂºÂ I
  // ==========================================================

  const hasVariantFilter =
    requestedStorage !== null ||
    requestedRam !== null ||
    Boolean(requestedColor);

  if (
    hasVariantFilter &&
    matchedVariants.length === 0
  ) {

    missingProducts.push({

      index:
        requested.index ?? null,

      brand:
        requested.brand ?? null,

      model:
        requested.model ?? null,

      storage_gb:
        requestedStorage,

      ram_gb:
        requestedRam,

      color:
        requested.color ?? null,

      reason:
        'variant_not_found'
    });

    continue;
  }

  // ==========================================================
  // SORT VARIANTS
  //
  // CÄ‚Â²n hÄ‚Â ng trĂ†Â°Ă¡Â»â€ºc
  // Sau Ă„â€˜Ä‚Â³ giÄ‚Â¡ thĂ¡ÂºÂ¥p trĂ†Â°Ă¡Â»â€ºc
  // ==========================================================

  matchedVariants.sort(
    (a, b) => {

      if (
        a.availability !==
        b.availability
      ) {
        return (
          a.availability ===
          'in_stock'
        )
          ? -1
          : 1;
      }

      return a.price - b.price;
    }
  );

  // ==========================================================
  // IN-STOCK VARIANTS
  // ==========================================================

  const inStockVariants =
    matchedVariants.filter(
      variant =>
        variant.stock > 0
    );

  // ==========================================================
  // STOCK
  // ==========================================================

  const totalStock =
    matchedVariants.reduce(
      (
        sum,
        variant
      ) => {
        return (
          sum +
          variant.stock
        );
      },
      0
    );

  // ==========================================================
  // ALL PRICES
  // ==========================================================

  const allPrices =
    matchedVariants
      .map(
        variant =>
          variant.price
      )
      .filter(
        price =>
          Number.isFinite(price)
      );

  // ==========================================================
  // IN-STOCK PRICES
  // ==========================================================

  const inStockPrices =
    inStockVariants
      .map(
        variant =>
          variant.price
      )
      .filter(
        price =>
          Number.isFinite(price)
      );

  // ==========================================================
  // ALL STORAGES
  // ==========================================================

  const allStorages = [
    ...new Set(
      matchedVariants
        .map(
          variant =>
            variant.storage_gb
        )
        .filter(
          value =>
            value !== null &&
            value !== undefined
        )
    )
  ].sort(
    (a, b) =>
      a - b
  );

  // ==========================================================
  // IN-STOCK STORAGES
  // ==========================================================

  const inStockStorages = [
    ...new Set(
      inStockVariants
        .map(
          variant =>
            variant.storage_gb
        )
        .filter(
          value =>
            value !== null &&
            value !== undefined
        )
    )
  ].sort(
    (a, b) =>
      a - b
  );

  // ==========================================================
  // ALL COLORS
  // ==========================================================

  const allColors = [
    ...new Set(
      matchedVariants
        .map(
          variant =>
            variant.color
        )
        .filter(Boolean)
    )
  ];

  // ==========================================================
  // IN-STOCK COLORS
  // ==========================================================

  const inStockColors = [
    ...new Set(
      inStockVariants
        .map(
          variant =>
            variant.color
        )
        .filter(Boolean)
    )
  ];

  // ==========================================================
  // PRODUCT IMAGE
  // ==========================================================

  const productImage =
    normalizeImageUrl(
      matchedProduct.image ||
      matchedVariants[0]?.image_url ||
      matchedProduct.images?.[0]
    );

  // ==========================================================
  // PRODUCT IMAGES
  // ==========================================================

  const productImages =
    Array.isArray(
      matchedProduct.images
    )
      ? matchedProduct.images
          .map(
            image =>
              normalizeImageUrl(image)
          )
          .filter(Boolean)
      : [];

  // ==========================================================
  // FINAL COMPARE PRODUCT
  // ==========================================================

  comparedProducts.push({

    // --------------------------------------------------------
    // Request metadata
    // --------------------------------------------------------

    requested_index:
      requested.index ?? null,

    requested_filters: {

      brand:
        requested.brand ?? null,

      model:
        requested.model ?? null,

      storage_gb:
        requestedStorage,

      ram_gb:
        requestedRam,

      color:
        requested.color ?? null
    },

    // --------------------------------------------------------
    // Product
    // --------------------------------------------------------

    id:
      matchedProduct.id,

    name:
      matchedProduct.name,

    model:
      matchedProduct.name,

    brand:
      matchedProduct.brand ?? null,

    category:
      matchedProduct.category
        ? {
            id:
              matchedProduct
                .category.id,

            name:
              matchedProduct
                .category.name,

            slug:
              matchedProduct
                .category.slug
          }
        : null,

    description:
      matchedProduct.description ?? null,

    // --------------------------------------------------------
    // Images
    // --------------------------------------------------------

    image_url:
      productImage,

    images:
      productImages,

    // --------------------------------------------------------
    // Specifications
    // --------------------------------------------------------

    specifications:
      matchedProduct.specifications ?? [],

    screen:
      getSpecification(
        matchedProduct.specifications,
        'Màn hình'
      ),

    cpu:
      getSpecification(
        matchedProduct.specifications,
        'CPU'
      ) ||
      getSpecification(
        matchedProduct.specifications,
        'Chip'
      ),

    ram:
      getSpecification(
        matchedProduct.specifications,
        'RAM'
      ),

    camera:
      getSpecification(
        matchedProduct.specifications,
        'Camera'
      ),

    battery:
      getSpecification(
        matchedProduct.specifications,
        'Pin'
      ),

    operating_system:
      getSpecification(
        matchedProduct.specifications,
        'Hệ điều hành'
      ),

    // --------------------------------------------------------
    // Prices - tĂ¡ÂºÂ¥t cĂ¡ÂºÂ£ variant phÄ‚Â¹ hĂ¡Â»Â£p
    // --------------------------------------------------------

    price_min:
      allPrices.length
        ? Math.min(
            ...allPrices
          )
        : null,

    price_max:
      allPrices.length
        ? Math.max(
            ...allPrices
          )
        : null,

    // --------------------------------------------------------
    // Prices - chĂ¡Â»â€° variant cÄ‚Â²n hÄ‚Â ng
    // --------------------------------------------------------

    in_stock_price_min:
      inStockPrices.length
        ? Math.min(
            ...inStockPrices
          )
        : null,

    in_stock_price_max:
      inStockPrices.length
        ? Math.max(
            ...inStockPrices
          )
        : null,

    // --------------------------------------------------------
    // Stock
    // --------------------------------------------------------

    stock:
      totalStock,

    availability:
      inStockVariants.length > 0
        ? 'in_stock'
        : 'out_of_stock',

    // --------------------------------------------------------
    // Storage
    // --------------------------------------------------------

    all_storages:
      allStorages,

    in_stock_storages:
      inStockStorages,

    // --------------------------------------------------------
    // Colors
    // --------------------------------------------------------

    all_colors:
      allColors,

    in_stock_colors:
      inStockColors,

    // --------------------------------------------------------
    // Campaign
    // --------------------------------------------------------

    campaign:
      matchedProduct.activeCampaign
        ? {
            id:
              matchedProduct
                .activeCampaign.id,

            name:
              matchedProduct
                .activeCampaign.name,

            discountType:
              matchedProduct
                .activeCampaign
                .discountType,

            discountValue:
              matchedProduct
                .activeCampaign
                .discountValue
          }
        : null,

    // --------------------------------------------------------
    // Variants
    // --------------------------------------------------------

    variants:
      matchedVariants
  });
}

// ============================================================
// FINAL RESULT
// ============================================================

const totalRequested =
  requestedProducts.length;

const totalFound =
  comparedProducts.length;

// ============================================================
// COMPARE STATUS
// ============================================================

let compareStatus = 'not_found';

if (
  totalRequested >= 2 &&
  totalFound === totalRequested
) {
  const allRequestsSpecific =
    requestedProducts.every(request => {
      return (
        request.storage_gb !== null &&
        request.storage_gb !== undefined
      );
    });

  compareStatus =
    allRequestsSpecific
      ? 'ready'
      : 'needs_variant_selection';
}

// ============================================================
// OUTPUT
// ============================================================

return [
  {
    json: {
      result_type: 'product_compare',

      total:
        comparedProducts.length,

      total_requested:
        totalRequested,

      total_found:
        totalFound,

      compare_status:
        compareStatus,

      ready_to_compare:
        compareStatus === 'ready',

      products:
        comparedProducts,

      missing_products:
        missingProducts,

      chatInput:
        source.chatInput ?? '',

      sessionId:
        source.sessionId ?? '',

      source:
        source.source ?? 'web_chat'
    }
  }
];

