parameters.jsCode:
const source =
  $('Prepare Recommendation Filters').first().json;

const filters =
  source.filters || {};

// ============================================================
// HELPERS
// ============================================================

function normalizeText(value) {
  return String(value ?? '')
    .normalize('NFD')
    .replace(/[\u0300-\u036f]/g, '')
    .replace(/Ă„â€˜/g, 'd')
    .replace(/Ă„Â/g, 'D')
    .toLowerCase()
    .trim();
}

function compactText(value) {
  return normalizeText(value)
    .replace(/[^a-z0-9]/g, '');
}

function parseCapacity(value) {
  if (
    value === null ||
    value === undefined ||
    value === ''
  ) {
    return null;
  }

  const text =
    normalizeText(value)
      .replace(/\s+/g, '');

  const match =
    text.match(
      /(\d+(?:\.\d+)?)(tb|gb)?/i
    );

  if (!match) {
    return null;
  }

  let number =
    Number(match[1]);

  if (!Number.isFinite(number)) {
    return null;
  }

  if (
    (match[2] || '')
      .toLowerCase() === 'tb'
  ) {
    number *= 1024;
  }

  return number;
}

function findAttribute(
  attributes,
  possibleNames
) {
  if (
    !attributes ||
    typeof attributes !== 'object'
  ) {
    return null;
  }

  for (
    const [key, value]
    of Object.entries(attributes)
  ) {
    const normalizedKey =
      normalizeText(key);

    const matched =
      possibleNames.some(name =>
        normalizedKey ===
        normalizeText(name)
      );

    if (matched) {
      return value;
    }
  }

  return null;
}

function getSpecification(
  specifications,
  keyword
) {
  if (!Array.isArray(specifications)) {
    return null;
  }

  const target =
    normalizeText(keyword);

  const item =
    specifications.find(spec => {
      const key =
        spec?.key ??
        spec?.name ??
        spec?.label ??
        '';

      return normalizeText(key)
        .includes(target);
    });

  return item?.value ?? null;
}

function extractVersionInfo(attributes) {
  const version =
    findAttribute(
      attributes,
      [
        'Phiên bản',
        'Phien ban',
        'Version'
      ]
    );

  if (!version) {
    return {
      storageGb: null,
      ramGb: null
    };
  }

  const matches = [
    ...String(version).matchAll(
      /(\d+(?:\.\d+)?)\s*(TB|GB)/gi
    )
  ];

  if (!matches.length) {
    return {
      storageGb: null,
      ramGb: null
    };
  }

  const values =
    matches.map(match => ({
      value: Number(match[1]),
      unit: match[2].toUpperCase()
    }));

  const tb =
    values.find(
      item => item.unit === 'TB'
    );

  if (tb) {
    const gbValues =
      values.filter(
        item => item.unit === 'GB'
      );

    return {
      storageGb:
        tb.value * 1024,

      ramGb:
        gbValues.length
          ? gbValues[0].value
          : null
    };
  }

  const gbValues =
    values
      .filter(
        item => item.unit === 'GB'
      )
      .map(
        item => item.value
      );

  if (gbValues.length >= 2) {
    return {
      ramGb:
        gbValues[0],

      storageGb:
        gbValues[
          gbValues.length - 1
        ]
    };
  }

  return {
    storageGb:
      gbValues.length === 1
        ? gbValues[0]
        : null,

    ramGb: null
  };
}

function normalizeImageUrl(value) {
  if (!value) {
    return null;
  }

  let text =
    String(value).trim();

  text = text.replace(
    /^https?:\/\/localhost:3001/,
    ''
  );

  text = text.replace(
    /^https?:\/\/127\.0\.0\.1:3001/,
    ''
  );

  text = text.replace(
    /^https?:\/\/host\.docker\.internal:3001/,
    ''
  );

  return text || null;
}

function calculateCampaignPrice(
  price,
  campaign
) {
  const originalPrice =
    Number(price);

  if (!Number.isFinite(originalPrice)) {
    return 0;
  }

  if (!campaign) {
    return originalPrice;
  }

  const discountValue =
    Number(
      campaign.discountValue
    ) || 0;

  if (
    campaign.discountType ===
    'percentage'
  ) {
    return Math.max(
      0,
      Math.round(
        originalPrice -
        (
          originalPrice *
          discountValue /
          100
        )
      )
    );
  }

  if (
    campaign.discountType ===
    'fixed'
  ) {
    return Math.max(
      0,
      originalPrice -
      discountValue
    );
  }

  return originalPrice;
}

// ============================================================

// ============================================================
const contextState = source.conversationState && typeof source.conversationState === 'object'
  ? source.conversationState
  : {};

function contextNormalize(value) {
  return String(value ?? '')
    .replace(/[đĐ]/g, 'd')
    .normalize('NFD')
    .replace(/[\u0300-\u036f]/g, '')
    .toLowerCase()
    .replace(/[^a-z0-9]+/g, ' ')
    .trim();
}

const contextCanonicalBrands = new Set([
  'apple', 'samsung', 'xiaomi', 'oppo', 'oneplus', 'vivo', 'honor', 'google', 'huawei', 'realme'
]);

function contextCanonicalBrand(value) {
  const text = contextNormalize(value);
  if (!text) return null;

  for (const brand of contextCanonicalBrands) {
    if (text === brand) {
      return brand;
    }
  }

  return null;
}

function unique(values) {
  return [...new Set(values.filter(Boolean))];
}

const contextCategory = source.category || contextState.category || null;
const contextExcludedBrands = unique([
  ...(Array.isArray(source.exclude_brands) ? source.exclude_brands : []),
  ...(Array.isArray(source.excluded_brands) ? source.excluded_brands : []),
  ...(Array.isArray(contextState.excluded_brands) ? contextState.excluded_brands : [])
].map(contextCanonicalBrand));
const contextExcludedForFilter = contextExcludedBrands;
const contextPreferredBrands = unique([
  ...(Array.isArray(source.preferred_brands) ? source.preferred_brands : []),
  ...(Array.isArray(contextState.preferred_brands) ? contextState.preferred_brands : [])
].map(contextCanonicalBrand));
const contextBrandSwitch =
  source.turn_action === 'EXCLUDE' &&
  contextExcludedBrands.some(brand => contextPreferredBrands.includes(brand));

const contextRejectedProducts = Array.isArray(contextState.rejected_products)
  ? contextState.rejected_products.filter(product => product && product.id)
  : [];
const contextRejectedProductIds = new Set(contextRejectedProducts.map(product => String(product.id)));
const contextRejectedPrices = contextRejectedProducts
  .map(product => Number(product.price_min ?? product.price_max ?? product.price))
  .filter(Number.isFinite);
const contextStrictLowerPrice =
  source.turn_action === 'REJECT' &&
  source.price_direction === 'lower' &&
  contextRejectedPrices.length > 0
    ? Math.min(...contextRejectedPrices)
    : null;
const contextIsPriceRejection =
  source.turn_action === 'REJECT' &&
  source.price_direction === 'lower' &&
  contextRejectedProducts.length > 0;

const contextRequestedBrand = contextIsPriceRejection || source.turn_action === 'EXCLUDE'
  ? null
  : contextCanonicalBrand(source.brand) ||
    contextCanonicalBrand(filters.brand) ||
    contextCanonicalBrand(contextState.active_filters?.brand) ||
    null;

function contextProductMatchesBrand(product, brand) {
  if (!brand) return false;

  const values = [
    product?.brand,
    product?.category?.name,
    product?.category?.slug,
    product?.name
  ];

  return values.some(value =>
    contextCanonicalBrand(value) === brand
  );
}

function contextProductMatchesCategory(product, category) {
  if (!category) return true;

  const categoryText = contextNormalize([
    product?.category?.name,
    product?.category?.slug,
    product?.name,
    product?.brand
  ].filter(Boolean).join(' '));

  if (category === 'phone') {
    if (
      /watch|smartwatch|dong ho|tablet|ipad|laptop|macbook/.test(categoryText)
    ) {
      return false;
    }

    return (
      /dien thoai|smartphone|iphone|galaxy|redmi|poco|xiaomi|oppo|oneplus|samsung|apple/.test(categoryText)
    );
  }

  if (category === 'watch') {
    return /watch|smartwatch|dong ho/.test(categoryText);
  }

  if (category === 'laptop') {
    return /laptop|macbook|may tinh xach tay/.test(categoryText);
  }

  if (category === 'tablet') {
    return /tablet|ipad|may tinh bang/.test(categoryText);
  }

  return true;
}

// NORMALIZE FILTERS
// ============================================================

const routedBrandFilter =
  normalizeText(
    filters.brand
  );

const brandFilter = source.turn_action === 'EXCLUDE'
  ? ''
  : contextRequestedBrand || routedBrandFilter;

const modelFilter =
  compactText(
    filters.model
  );

const colorFilter =
  normalizeText(
    filters.color
  );

const storageFilter =
  parseCapacity(
    filters.storage
  );

const ramFilter =
  parseCapacity(
    filters.ram
  );

let priceMax = null;

if (
  filters.price_max !== null &&
  filters.price_max !== undefined &&
  filters.price_max !== ''
) {
  const value =
    Number(filters.price_max);

  if (Number.isFinite(value)) {
    priceMax = value;
  }
}

const priceBelow = Number(filters.price_below ?? source.refinement_price_below);
if (source.price_direction === 'lower' && Number.isFinite(priceBelow) && priceBelow > 0) {
  const strictCeiling = Math.max(0, priceBelow - 1);
  priceMax = priceMax === null ? strictCeiling : Math.min(priceMax, strictCeiling);
} else if (priceMax === null && source.price_direction === 'lower') {
  const reference = Array.isArray(contextState.last_result_set)
    ? contextState.last_result_set.find(item => item.id === contextState.selected_product_id)
    : null;
  const referencePrice = Number(reference?.price_min ?? reference?.price_max);
  if (Number.isFinite(referencePrice)) priceMax = Math.max(0, referencePrice - 1);
}

const conditionFilter =
  normalizeText(
    filters.condition
  );

const useCase =
  normalizeText(
    filters.use_case
  );

// ============================================================
// API RESPONSE
// ============================================================

const items =
  $input.all();

let apiProducts = [];

if (
  items.length === 1 &&
  Array.isArray(items[0].json)
) {
  apiProducts =
    items[0].json;
} else if (
  items.length === 1 &&
  items[0].json &&
  Array.isArray(items[0].json.data)
) {
  // /api/products/search returns a pagination envelope.
  // Unwrap only its data array before applying deterministic context filters.
  apiProducts =
    items[0].json.data;
} else {
  apiProducts =
    items.map(
      item => item.json
    );
}

// ============================================================
// ACTIVE PRODUCTS
// ============================================================

apiProducts =
  apiProducts.filter(product => {

    if (
      normalizeText(
        product.status
      ) !== 'active'
    ) {
      return false;
    }

    if (
      product.category?.isActive === false
    ) {
      return false;
    }

    return true;
  });

// ============================================================
// BUILD CANDIDATES
// ============================================================

const candidates = [];

for (
  const product
  of apiProducts
) {

  if (
    contextCategory &&
    !contextProductMatchesCategory(product, contextCategory)
  ) {
    continue;
  }

    if (
      contextExcludedForFilter.some(brand =>
        contextProductMatchesBrand(product, brand)
      )
    ) {
      continue;
    }

    if (contextRejectedProductIds.has(String(product?.id))) {
      continue;
    }

    if (
      contextRequestedBrand &&
    !contextProductMatchesBrand(product, contextRequestedBrand)
  ) {
    continue;
  }


  // ==========================================================
  // BRAND FILTER
  // ==========================================================

  if (brandFilter) {

    const productBrand =
      normalizeText(
        product.brand
      );

    const categoryName =
      normalizeText(
        product.category?.name
      );

    const categorySlug =
      normalizeText(
        product.category?.slug
      );

    if (
      productBrand !== brandFilter &&
      categoryName !== brandFilter &&
      categorySlug !== brandFilter
    ) {
      continue;
    }
  }

  // ==========================================================
  // MODEL FILTER
  // ==========================================================

  if (modelFilter) {

    const productModel =
      compactText(
        product.name
      );

    if (
      !productModel.includes(
        modelFilter
      ) &&
      !modelFilter.includes(
        productModel
      )
    ) {
      continue;
    }
  }

  // ==========================================================
  // CONDITION FILTER
  //
  // ChĂ¡Â»â€° enforce nĂ¡ÂºÂ¿u API thĂ¡Â»Â±c sĂ¡Â»Â± cÄ‚Â³ dĂ¡Â»Â¯ liĂ¡Â»â€¡u condition.
  // KhÄ‚Â´ng tĂ¡Â»Â± giĂ¡ÂºÂ£ Ă„â€˜Ă¡Â»â€¹nh "new".
  // ==========================================================

  if (conditionFilter) {

    const productCondition =
      normalizeText(
        product.condition ??
        product.conditionType ??
        product.condition_type
      );

    if (!productCondition) {
      continue;
    }

    if (
      productCondition !==
      conditionFilter
    ) {
      continue;
    }
  }

  const variants =
    Array.isArray(
      product.variants
    )
      ? product.variants
      : [];

  const matchedVariants = [];

  for (
    const variant
    of variants
  ) {

    // Recommendation:
    // CHĂ¡Â»Ë† tĂ†Â° vĂ¡ÂºÂ¥n variant Ă„â€˜ang cÄ‚Â²n hÄ‚Â ng.
    const stock =
      Number(
        variant.stock
      ) || 0;

    if (stock <= 0) {
      continue;
    }

    const storageRaw =
      findAttribute(
        variant.attributes,
        [
          'Dung lÆ°á»£ng',
          'Dung luong',
          'Storage',
          'SSD'
        ]
      );

    const directRam =
      findAttribute(
        variant.attributes,
        ['RAM']
      );

    const colorRaw =
      findAttribute(
        variant.attributes,
        [
          'Màu sắc',
          'Mau sac',
          'Color'
        ]
      );

    const versionInfo =
      extractVersionInfo(
        variant.attributes
      );

    let storageGb =
      parseCapacity(
        storageRaw
      );

    let ramGb =
      parseCapacity(
        directRam
      );

    if (storageGb === null) {
      storageGb =
        versionInfo.storageGb;
    }

    if (ramGb === null) {
      ramGb =
        versionInfo.ramGb;
    }

    if (ramGb === null) {
      ramGb =
        parseCapacity(
          getSpecification(
            product.specifications,
            'RAM'
          )
        );
    }

    // ========================================================
    // STORAGE FILTER
    // ========================================================

    if (
      storageFilter !== null &&
      storageGb !== storageFilter
    ) {
      continue;
    }

    // ========================================================
    // RAM FILTER
    // ========================================================

    if (
      ramFilter !== null &&
      ramGb !== ramFilter
    ) {
      continue;
    }

    // ========================================================
    // COLOR FILTER
    // ========================================================

    if (colorFilter) {

      if (
        !normalizeText(
          colorRaw
        ).includes(
          colorFilter
        )
      ) {
        continue;
      }
    }

    // ========================================================
    // PRICE
    // ========================================================

    const originalPrice =
      Number(
        variant.price
      ) || 0;

    if (!Number.isFinite(originalPrice) || originalPrice <= 0) continue;
    const candidateSalePrice = Number(variant.salePrice);
    const validSalePrice = variant.salePrice != null && variant.salePrice !== '' &&
      Number.isFinite(candidateSalePrice) && candidateSalePrice > 0 && candidateSalePrice < originalPrice;
    const price = product.activeCampaign
      ? calculateCampaignPrice(originalPrice, product.activeCampaign)
      : (validSalePrice ? candidateSalePrice : originalPrice);

    if (
      priceMax !== null &&
      price > priceMax
    ) {
      continue;
    }

    if (
      contextStrictLowerPrice !== null &&
      price >= contextStrictLowerPrice
    ) {
      continue;
    }

    matchedVariants.push({

      id:
        variant.id,

      sku:
        variant.sku,

      attributes:
        variant.attributes ?? {},

      storage_gb:
        storageGb,

      ram_gb:
        ramGb,

      color:
        colorRaw ?? null,

      color_code:
        variant.colorCode ?? null,

      original_price:
        originalPrice,

      price,

      stock,

      availability:
        'in_stock',

      image_url:
        normalizeImageUrl(
          variant.image ||
          product.image ||
          product.images?.[0]
        )
    });
  }

  if (
    matchedVariants.length === 0
  ) {
    continue;
  }

  matchedVariants.sort(
    (a, b) =>
      a.price - b.price
  );

  const prices =
    matchedVariants.map(
      variant =>
        variant.price
    );

  const totalStock =
    matchedVariants.reduce(
      (sum, variant) =>
        sum + variant.stock,
      0
    );

  candidates.push({

    id:
      product.id,

