  ...(typeof pending.type === "string" ? { type: pending.type.slice(0, 40) } : {}),
  ...(typeof pending.field === "string" ? { field: pending.field.slice(0, 40) } : {}),
  ...(typeof pending.product_id === "string" ? { product_id: pending.product_id.slice(0, 128) } : {}),
  ...(typeof pending.product_name === "string" ? { product_name: pending.product_name.slice(0, 160) } : {})
} : null;
const conversationState = {
  category: stateCategory,
  active_filters: activeFilters,
  preferred_brands: preferredBrands,
  excluded_brands: excludedBrands,
  rejected_products: safeRejectedProducts,
  last_result_set: safeLastResultSet,
  selected_product_id: selectedProductId,
  selected_variant_id: router.context_mode === 'reset' ? null : (previous.selected_variant_id || null),
  last_intent: router.intent || previous.last_intent || null,
  last_turn_action: router.turn_action || previous.last_turn_action || 'CONTINUE',
  pending_question: safePending,
  state_version: 2,
  updated_at: new Date().toISOString()
};

const resultType = ["product_search", "product_detail", "product_compare", "recommendation", "faq", "text"].includes(String(input.result_type || ""))
  ? String(input.result_type)
  : "text";
const productCandidates = [
  ...(Array.isArray(input.products) ? input.products : []),
  ...(input.product && typeof input.product === "object" ? [input.product] : [])
];
const productIds = [...new Set(productCandidates.flatMap(product => {
  const id = product && typeof product === "object" ? String(product.id || product.product?.id || "").trim() : "";
  return id ? [id.slice(0, 128)] : [];
}))].slice(0, 12).map(id => ({ id }));
const safeResponse = router.turn_action === "CANCEL"
  ? "Quotation status and cancellation are managed in the authenticated WebPhone account; this chatbot cannot verify or cancel a quotation."
  : resultType === "faq" && typeof input.response === "string"
  ? input.response.slice(0, 4000)
  : resultType === "product_search" || resultType === "product_detail" || resultType === "product_compare" || resultType === "recommendation"
    ? "Product suggestions are sent to the WebPhone Backend for catalog validation."
    : "I can help find products and verified store information.";
const output = {
  json: {
    result_type: resultType,
    response_type: "text",
    response: safeResponse,
    sessionId: String(input.sessionId || normalizeInput.sessionId || "").slice(0, 100),
    conversation_state: conversationState
  }
};
if (["product_search", "product_detail", "product_compare", "recommendation"].includes(resultType)) {
  output.json.products = productIds;
}
return output;
